INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '企业对于微生物（如细菌、病毒、朊病毒等）的危害防控措施，可以采用清洁消毒、加热灭菌、低温贮存、添加防腐剂、建立不利于微生物生存繁殖的环境等措施，也可以加强源头控制，消除或降低原料带入产生的危害风险。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '有发生食品安全事故潜在风险的，在开展食品生产经营同时，向所在地县级人民政府食品安全监督管理部门报告。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '设计和管控产品配方时，应明确产品在GB 2760中的类别定位，进行食品添加剂合规性审查，确定可以使用的食品添加剂品种和添加量。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '再制蛋的生产工艺为：选蛋→打蛋去壳→搅拌过滤→低温杀菌→干燥→包装。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '不经脱水干燥的主食类方便食品和调味面制品更容易在生产过程中受到微生物污染。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '《食品安全国家标准 豆制品》（GB 2712-2014）中脲酶试验仅适用于豆浆。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食品加工人员取得健康证明后无需卫生培训可直接上岗。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '墙面、隔断应使用无毒、无味的防渗透材料建造，在操作高度范围内的墙面应光滑、不易积累污垢且易于清洁。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '通常情况下，食品安全自查内容应当至少包括获得许可的生产经营条件保持情况和各项食品安全管理制度落实情况。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '人员手部、设备设施、工器具等食品接触面清洗消毒不彻底，可能污染产品，造成产品微生物超标。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
