INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '啤酒标签除酒精度、原麦汁浓度、警示语和保质期的标识外，应符合GB7718的规定', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '单一品种的食用植物油、食用动物油脂不应掺杂其他油脂。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
