INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食品生产人员应当保持个人卫生，生产食品时，应当将手洗净，穿戴清洁的工作衣、帽。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
