INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食醋生产企业应具备与生产能力相适应的厂房、原辅材料仓库、成品仓库和化验室。生产用厂房能满足原料处理、种曲（外协的除外）和制曲、液化及糖化、酒精发酵、醋酸发酵、淋醋、调配、灭菌处理和灌装（包装）的工艺要求。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食品生产企业应当按照食品安全国家标准使用食品添加剂。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食品生产企业应当具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品交叉污染，避免食品接触有毒物、不洁物。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '复配食品添加剂是指为了改善食品品质、便于食品加工，将两种或两种以上单一品种的食品添加剂，添加或不添加辅料，经物理方法混匀而成的食品添加剂。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食醋生产企业自培菌种、酒化、醋化等工序应有通风、降温、保温设施，以满足工艺规程的需要。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '《小麦粉》（GB/T 1355）规定外观形态应为粉状或微粒状，有结块。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食品生产许可实行一企一证原则，同一个食品生产者从事食品生产活动，应当取得一个食品生产许可证。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
