INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '膨化食品中致病菌限量应符合ＧＢ２９９２１中熟制粮食制品类的规定。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '应做好酿酒原料的收购储存， 防止霉烂变质，以免带来真菌毒素如展青霉素、赭曲霉毒素A 等污染。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '在食品生产、流通、销售等环节自然发生的，通过人流、物流以及环境、设备等带入食品中的生物、化学和物理污染风险，属于非传统风险。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '速冻食品生产中需加强食品生产加工过程控制，严格按照GB 2760的规定使用食品添加剂，按期对食品添加剂称量设备等进行校准，确保投料的准确性。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '《食品安全国家标准 运动营养食品》（GB 24154-2015）规定，对于添加了牛磺酸的产品应在标签中标示“孕妇、哺乳期妇女、儿童及婴幼儿不适宜食用”。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '糕点生产车间根据清洁程度通常可划分为清洁作业区、准清洁作业区和一般作业区。一般作业区应与其他作业区域分隔。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '复检结论与初检结论一致的，复检费用由复检申请人承担。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '食醋类生产许可包括酿造食醋、配制食醋和甜醋。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
