INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品生产', '易', '是', NULL, '请判断以下行为是否正确。某一红薯淀粉生产企业取得淀粉生产许可证后，发现红薯粉丝市场较大，于是立即租用设备，使用其生产的红薯淀粉进一步生产红薯粉丝（）。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
