INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '从业人员在食品经营过程中，可以适当饮食、吸烟。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '冷库温度记录和显示设备宜放置在冷库外便于查看和控制的地方，温度传感器或温度记录仪应当放置在最能反映食品温度或平均温度的位置。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '普通食品、特殊食品、药品不得混放销售。普通食品与特殊食品之间、与药品之间应当有明显的隔离标识或保持一定距离摆放。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员，自处罚决定作出之日起五年内不得申请食品经营许可，不得从事食品生产经营管理工作、担任食品生产经营企业食品安全总监、食品安全员等食品安全管理人员。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', NULL, '否', NULL, '食品经营者申请通过网络经营、建立中央厨房或者从事集体用餐配送的，应当在主体业态后以括号标注。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品经营者采购的进口食品在进货查验时发现没有中文标签也可以进货入库进行销售。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '需冷冻的食品运输过程温度、贮存环境温度不高于-18℃。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '食品检验机构的资质认定条件和检验规范，由国务院卫生行政部门规定。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '出现食品安全事故后，事故单位只向事故发生地市场监督管理部门报告。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '预包装食品首先应当预先包装，此外包装上要有统一的质量或体积的标示。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核。经考核不具备食品安全管理能力的，不得上岗。食品安全监督管理部门应当对企业食品安全管理人员随机进行监督抽查考核并公布考核情况。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', NULL, '否', NULL, '申请食品经营许可，应当先取得营业执照等合法主体资格。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品安全管理人员监督抽查考核不得公布考核结果。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '食品生产经营者在集中销毁处理前，应当向所在地县级人民政府食品安全监督管理部门报告报告。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '取得食品生产许可的食品生产者，在其生产加工场所或通过网络销售其生产的食品的，不需要取得食品经营许可。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '食品生产经营者需要对召回的食品进行无害化处理、销毁的，应当提前报告时间、地点。食品安全监督管理部门应当实施现场监督。', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '各岗位从业人员应当根据本企业培训制度，参加食品安全知识培训。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品经过预先包装则属于预包装食品', '错', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品经营者应查验所采购食品、食品添加剂的感官性状等质量安全状况。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '对违法添加非食用物质、腐败变质、病死畜禽等严重危害人体健康和生命安全的不安全食品，应当立即就地销毁。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '利用自动设备仅销售预包装食品的，备案人应当提交每台设备的具体放置地点、备案编号的展示方法、食品安全风险管控方案等材料。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
