INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '预包装食品，指预先定量包装或者制作在包装材料、容器中的食品，包括预先定量包装以及预先定量制作在包装材料和容器中，并且在一定量限范围内，具有统一的质量或体积标识的食品。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '销售直接入口散装食品的从业人员，应当在每天上岗前对其进行健康状况检查并记录检查情况。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '从经营单位采购食品的，查看其食品经营许可证（或复印件），或《仅销售预包装食品经营者备案信息采集表》；查看生产单位出具的食品出厂检验合格证，或生产单位委托检验机构出具的检验合格报告等其他合格证明。采购进口食品的，还应当查看海关出具的入境货物检验检疫证明，确保每一批次货证相符。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品在宣传及广告中不得编造、散布虚假食品安全信息。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
