INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '否', NULL, '发生食品安全事故的单位应当立即采取措施，防止事故扩大。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.questions (question_type, business_type, difficulty, is_required, remark, question_content, answer, option_a, option_b, option_c, option_d, option_e, option_f, option_g, option_h, option_i, option_j) VALUES ('判断题', '食品流通', '易', '是', NULL, '食品经营许可证遗失、损坏，应当向原发证的市场监督管理部门申请补办，并提交食品经营许可证补办申请书、书面遗失声明或受损坏的食品经营许可证。因遗失、损坏补发的食品经营许可证，许可证编号不变，发证日期和有效期与原证书保持一致。', '对', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
